def clamp(x, low, high):
    return max(low, min(x, high))


def clamp_no_upper(x, low, high):
    return max(low, x)


def clamp_no_lower(x, low, high):
    return min(x, high)


def check_clamp(impl):
    assert impl(5, 0, 10) == 5
    assert impl(-3, 0, 10) == 0
    assert impl(15, 0, 10) == 10


def verdict(check, impl):
    try:
        check(impl)
        return "PASS"
    except Exception:
        return "FAIL"


print(verdict(check_clamp, clamp))
print(verdict(check_clamp, clamp_no_upper))
print(verdict(check_clamp, clamp_no_lower))

